#!/usr/bin/env bash
# Fails when a tracked code file is over its size cap, so that every file stays small enough for a
# person to keep in their head: production 1000 lines, tests 1500. In a Rust source file the code
# outside its top-level `#[cfg(test)]` blocks is production (cap 1000) and the whole file is capped
# at 1500. Generated code (`gen/`, `autogenerated/`), documents and lockfiles are not measured.
#
# The files over their cap today are listed in `.file-size-allow`, one per line with a ceiling (the
# list's header gives the format), and the list can only shrink: a listed file may not pass its
# ceiling, the ceiling is the file's size rounded up to the hundred, a file that fits comes off the
# list, and against the commit where HEAD leaves `origin/main` (their merge-base) the list may not
# gain a path or raise a ceiling. The merge-base, not the tip of main: a release of an older tag, or
# a branch cut before main lowered a ceiling, keeps the ceilings it was built with.
#
# Usage: file-size.sh [checkout] [main]   (defaults: the current directory, origin/main)
# Exit:  0 within the caps · 1 a file or a list line breaks them, one line each
#        2 cannot judge: not a git checkout, main is missing or shares no history with HEAD, or
#          the list is malformed
set -uo pipefail

root=${1:-.}
main=${2:-origin/main}
list=.file-size-allow

if ! top=$(git -C "$root" rev-parse --show-toplevel 2>/dev/null); then
    echo "::error::$root is not a git checkout" >&2
    exit 2
fi
cd "$top" || exit 2

# Without a base the ratchet cannot be judged, and skipping it would let the list grow unseen.
if ! git rev-parse --verify --quiet "$main^{commit}" >/dev/null; then
    echo "::error::$main is not in this checkout: run git fetch origin main (the list can only shrink against it)" >&2
    exit 2
fi
if ! base=$(git merge-base HEAD "$main" 2>/dev/null); then
    echo "::error::HEAD and $main share no history in this checkout: fetch the whole history (git fetch --unshallow origin) so the list has a base to shrink against" >&2
    exit 2
fi
base_label="$main@$(git rev-parse --short "$base")"

work=$(mktemp -d "${TMPDIR:-/tmp}/erplora-file-size.XXXXXX")
trap 'rm -rf "$work"' EXIT

: > "$work/base"
if git cat-file -e "$base:$list" 2>/dev/null; then
    git show "$base:$list" > "$work/base"
    has_base=1
else
    # Only true on the commit that brings the list: after it, the base always has one.
    echo "$base_label has no $list: the ratchet starts with this list"
    has_base=0
fi

files=()
while IFS= read -r path; do
    [ -s "$path" ] && files+=("$path")
done < <(git -c core.quotepath=off ls-files \
    | grep -E '\.(rs|kt|kts|java|gradle|ts|tsx|js|jsx|mjs|cjs|sh|html|css|py|ps1|yml)$' \
    | grep -vE '(^|/)(gen|autogenerated)/')
# awk with no file would read stdin.
[ ${#files[@]} -gt 0 ] || files=(/dev/null)

# One awk pass measures every file and then judges the measures against both lists.
awk -v list_file="$list" -v base_file="$work/base" -v has_base="$has_base" -v base_list="the $list of $base_label" '
function is_test(p) { return p ~ /(^|\/)(tests?|android-tests)\// || p ~ /\.test\.[A-Za-z]+$/ }
function kind_of(p) { return is_test(p) ? "test" : (p ~ /\.rs$/ ? "rust" : "code") }
function up(x) { return int((x + 99) / 100) * 100 }
function err(p, msg) { printf "::error file=%s::%s: %s\n", p, p, msg; broken = 1 }
function bad_line(n, text, why) { printf "::error file=%s,line=%d::%s (%s)\n", list_file, n, why, text; malformed = 1 }

function flush() {
    if (cur == "") return
    whole[cur] = total
    prod[cur] = total - in_tests
    measured[++count] = cur
}

# A ceiling: a number, or for a Rust source file <production>/<whole file>, "-" for a part that is
# within its cap. Returns the shape ("plain" or "rust"), or "" when it is not a ceiling.
function shape_of(c,    parts, n) {
    if (c ~ /^[0-9]+$/) return "plain"
    n = split(c, parts, "/")
    if (n == 2 && c != "-/-" && parts[1] ~ /^([0-9]+|-)$/ && parts[2] ~ /^([0-9]+|-)$/) return "rust"
    return ""
}

function read_list(file, into, validate,    line, n, f, k) {
    n = 0
    while ((getline line < file) > 0) {
        n++
        if (line ~ /^[ \t]*(#|$)/) continue
        k = split(line, f, /[ \t]+/)
        if (!validate) { into[f[2]] = f[1]; continue }
        if (k != 3) { bad_line(n, line, "expected <ceiling> <path> <issue>"); continue }
        if (shape_of(f[1]) == "") { bad_line(n, line, "the ceiling is a number, or <production>/<whole> for Rust"); continue }
        if (f[3] !~ /^[A-Za-z0-9_.\/-]*#[0-9]+$/) { bad_line(n, line, "the third field is the issue, app#N"); continue }
        if (f[2] in into) { bad_line(n, line, "the path is listed twice"); continue }
        into[f[2]] = f[1]
        listed_at[f[2]] = n
    }
    close(file)
}

# One measured part against its ceiling ("-" = the plain cap applies).
function check_part(p, value, ceiling, cap, label, cap_name) {
    if (ceiling == "-") {
        if (value > cap) err(p, value " " label ", over the " cap_name " cap of " cap)
        return 0
    }
    if (value > ceiling + 0) { err(p, value " " label ", over its ceiling of " ceiling); return 0 }
    if (value <= cap) return 1
    if (ceiling + 0 > up(value)) err(p, "ceiling " ceiling " is loose for " value " " label ": lower it to " up(value))
    return 0
}

function check_unlisted(p, k) {
    if (k == "rust") {
        check_part(p, prod[p], "-", 1000, "production lines", "production")
        check_part(p, whole[p], "-", 1500, "lines in all", "whole-file")
    } else if (k == "test") {
        check_part(p, whole[p], "-", 1500, "lines", "tests")
    } else {
        check_part(p, whole[p], "-", 1000, "lines", "production")
    }
}

function check_listed(p, k, c,    parts, cap, fits_p, fits_w) {
    if (k != "rust") {
        cap = (k == "test") ? 1500 : 1000
        if (check_part(p, whole[p], c, cap, "lines", k == "test" ? "tests" : "production"))
            err(p, whole[p] " lines fit under the cap of " cap ": remove it from " list_file)
        return
    }
    split(c, parts, "/")
    fits_p = check_part(p, prod[p], parts[1], 1000, "production lines", "production")
    fits_w = check_part(p, whole[p], parts[2], 1500, "lines in all", "whole-file")
    if ((fits_p || parts[1] == "-") && (fits_w || parts[2] == "-") && prod[p] <= 1000 && whole[p] <= 1500)
        err(p, prod[p] " production lines and " whole[p] " in all fit under the caps: remove it from " list_file)
    else if (fits_p)
        err(p, prod[p] " production lines fit under the cap of 1000: write - for that part")
    else if (fits_w)
        err(p, whole[p] " lines in all fit under the cap of 1500: write - for that part")
}

# Against the base list: no new path, and no part of a ceiling goes up (from "-" to a number counts).
function check_ratchet(p, c,    hp, bp, n, i) {
    if (!(p in base_ceiling)) { err(p, "new exception, not in " base_list); return }
    n = split(c, hp, "/")
    if (n != split(base_ceiling[p], bp, "/")) { err(p, "raises its ceiling from " base_ceiling[p] " to " c); return }
    for (i = 1; i <= n; i++) {
        if (hp[i] != "-" && (bp[i] == "-" || hp[i] + 0 > bp[i] + 0)) {
            err(p, "raises its ceiling from " base_ceiling[p] " to " c)
            return
        }
    }
}

FNR == 1 { flush(); cur = FILENAME; in_tests = 0; state = 0; rust = (kind_of(cur) == "rust") }
{ total = FNR }

# Rust: a top-level `#[cfg(test)]` and the item it gates, up to the closing brace of that item at
# column 0 (or its `;`), are tests. Other attributes and comments in between belong to the item.
rust && state == 0 && /^#\[cfg\(test\)\]/ { state = 1; in_tests++; next }
rust && state == 1 {
    in_tests++
    if ($0 ~ /^[ \t]*$/ || $0 ~ /^#/ || $0 ~ /^[ \t]*\/\//) next
    if ($0 ~ /\{[ \t]*$/) { state = 2; next }
    if ($0 ~ /[;}][ \t]*$/) state = 0
    next
}
rust && state == 2 { in_tests++; if ($0 ~ /^\}/) state = 0; next }

END {
    flush()
    read_list(list_file, ceiling, 1)
    if (has_base) read_list(base_file, base_ceiling, 0)
    for (p in ceiling) {
        if (shape_of(ceiling[p]) == "rust" && kind_of(p) != "rust")
            bad_line(listed_at[p], ceiling[p] " " p, "only a Rust source file takes <production>/<whole>")
        if (shape_of(ceiling[p]) == "plain" && kind_of(p) == "rust")
            bad_line(listed_at[p], ceiling[p] " " p, "a Rust source file takes <production>/<whole>, - for a part within its cap")
    }
    if (malformed) exit 2

    for (i = 1; i <= count; i++) {
        p = measured[i]
        seen[p] = 1
        if (p in ceiling) check_listed(p, kind_of(p), ceiling[p])
        else check_unlisted(p, kind_of(p))
    }
    for (p in ceiling) {
        if (!(p in seen)) err(p, "listed in " list_file " but not tracked: remove the line")
        else if (has_base) check_ratchet(p, ceiling[p])
    }
    exit broken ? 1 : 0
}
' "${files[@]}"
status=$?

if [ "$status" -eq 0 ]; then
    echo "every tracked code file is within its cap, or within its ceiling in $list"
    exit 0
fi
if [ "$status" -eq 1 ]; then
    cat >&2 <<'HINT'

A file over its cap is split by responsibility, in a pull request of its own that only moves code.
A listed file can shrink, and then its ceiling comes down with it; it can never grow past it, and
a new file never joins the list. A ceiling is the file's size rounded up to the hundred.
HINT
fi
exit "$status"
